    n_cat, n_sig = run(new, cat, src, t, s)
    def fmt(c, sg): return ("—" if c is None else c[:2] + sg)
    if exp == "DROP": ok = n_cat is None
    elif exp == "KEEP": ok = n_cat is not None
    else: ok = n_cat == exp
    bad += (not ok)
    print(f"{'✅' if ok else '❌'} {exp[:5]:5} {fmt(o_cat,o_sig):14} {fmt(n_cat,n_sig):14}  {t[:70]}")
